"""Synthetic source-boundary fixtures only; no corpus, tokenizer or model reads."""
import copy
import hashlib
import json
from pathlib import Path
import sys
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parent))
from boundary_parser import BoundaryStop, prepare_partition


CORPUS = "c" * 64


def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def ledger_for(rows, choices):
    # Choices are explicit expected semantic decisions, not generated by parser.
    return {"row_count": len(rows), "corpus_sha256": CORPUS,
            "rows_sha256": digest(json.dumps(rows, ensure_ascii=False, sort_keys=True,
                                             separators=(",", ":")).encode("utf-8")),
            "decisions": [{"row": index, "row_sha256": digest(rows[index].encode("utf-8")),
                           "title": rows[index].strip(), "decision": decision,
                           "reason": "Synthetic fixture reviewed as " + decision}
                          for index, decision in choices]}


class BoundaryFixtures(unittest.TestCase):
    def assert_blocked(self, rows, ledger):
        with self.assertRaises(BoundaryStop) as caught:
            prepare_partition(rows, ledger, CORPUS)
        self.assertEqual(caught.exception.status, "BLOCKED")

    def test_formula_continuation_and_nested_section_stay_in_source_article(self):
        rows = [" \n", " = Alpha = \n", "\n", "lead\n", "= 2 =\n", "continued\n",
                "== Nested ==\n", "\n", "= Beta =\n", "tail\n"]
        ledger = ledger_for(rows, [(1, "ACCEPT_TITLE"), (4, "BODY"), (6, "BODY"), (8, "ACCEPT_TITLE")])
        result = prepare_partition(rows, ledger, CORPUS)
        self.assertEqual(result["leading_rows"], [0])
        self.assertEqual([a["heading_row"] for a in result["articles"]], [1, 8])
        self.assertEqual(result["articles"][0]["body_rows"], [2, 3, 4, 5, 6, 7])
        self.assertEqual(result["articles"][0]["parts"], ["\n", "lead\n", "= 2 =\n", "continued\n", "== Nested ==\n", "\n"])
        self.assertEqual(result["articles"][1]["parts"], ["tail\n"])
        roles = result["row_roles"]
        self.assertEqual([role["row"] for role in roles], list(range(10)))
        self.assertEqual([role["role"] for role in roles],
                         ["LEADING", "HEADING", "BODY", "BODY", "BODY", "BODY", "BODY", "BODY", "HEADING", "BODY"])
        self.assertEqual(roles[4]["source_article_key"], roles[1]["source_article_key"])
        self.assertNotEqual(roles[4]["source_article_key"], roles[8]["source_article_key"])
        reconstructed = result["leading_parts"][:]
        for article in result["articles"]:
            reconstructed += [article["heading_text"], *article["parts"]]
        self.assertEqual(reconstructed, rows)

    def test_blank_surrounded_formula_still_requires_explicit_body_decision(self):
        rows = ["= Source =\n", "text\n", "\n", "= x + y =\n", "\n", "equation explanation\n"]
        self.assert_blocked(rows, ledger_for(rows, [(0, "ACCEPT_TITLE")]))
        result = prepare_partition(rows, ledger_for(rows, [(0, "ACCEPT_TITLE"), (3, "BODY")]), CORPUS)
        self.assertEqual(len(result["articles"]), 1)
        self.assertEqual(result["articles"][0]["body_rows"], [1, 2, 3, 4, 5])

    def test_bof_eof_whitespace_and_no_blank_before_reviewed_title(self):
        rows = ["\t= First = \r\n", "body with trailing spaces  \n", " = Last =\t"]
        result = prepare_partition(rows, ledger_for(rows, [(0, "ACCEPT_TITLE"), (2, "ACCEPT_TITLE")]), CORPUS)
        self.assertEqual(result["leading_rows"], [])
        self.assertEqual(result["articles"][0]["title"], "= First =")
        self.assertEqual(result["articles"][0]["parts"], ["body with trailing spaces  \n"])
        self.assertEqual(result["articles"][1]["parts"], [])
        self.assertEqual(result["articles"][1]["heading_text"], " = Last =\t")

    def test_begin_or_end_candidates_both_need_ledger_and_cannot_be_titles(self):
        rows = ["= Article =\n", "= lhs + rhs\n", "calculation =\n", "== Section ==\n", "body\n"]
        complete = [(0, "ACCEPT_TITLE"), (1, "BODY"), (2, "BODY"), (3, "BODY")]
        self.assert_blocked(rows, ledger_for(rows, complete[:-1]))
        result = prepare_partition(rows, ledger_for(rows, complete), CORPUS)
        self.assertEqual(result["candidate_rows"], [0, 1, 2, 3])
        for index in (1, 2, 3):
            bad = ledger_for(rows, complete)
            bad["decisions"][index]["decision"] = "ACCEPT_TITLE"
            self.assert_blocked(rows, bad)

    def test_incorrect_corpus_rows_identity_and_raw_whitespace_are_blocked(self):
        rows = ["= A =\n", "body\n"]
        correct = ledger_for(rows, [(0, "ACCEPT_TITLE")])
        for field, value in (("row_count", 99), ("corpus_sha256", "d" * 64), ("rows_sha256", "e" * 64)):
            bad = copy.deepcopy(correct)
            bad[field] = value
            self.assert_blocked(rows, bad)
        for field, value in (("row_sha256", "f" * 64), ("title", "= Wrong =")):
            bad = copy.deepcopy(correct)
            bad["decisions"][0][field] = value
            self.assert_blocked(rows, bad)
        self.assert_blocked([" = A =\n", "body\n"], correct)

    def test_missing_duplicate_unknown_unresolved_and_reasonless_decisions_block(self):
        rows = ["= A =\n", "body\n"]
        correct = ledger_for(rows, [(0, "ACCEPT_TITLE")])
        variants = []
        missing = copy.deepcopy(correct)
        missing["decisions"] = []
        variants.append(missing)
        duplicate = copy.deepcopy(correct)
        duplicate["decisions"].append(copy.deepcopy(duplicate["decisions"][0]))
        variants.append(duplicate)
        for field, value in (("row", 1), ("row", True), ("decision", "UNRESOLVED"),
                             ("decision", "REJECT"), ("reason", " \n")):
            bad = copy.deepcopy(correct)
            bad["decisions"][0][field] = value
            variants.append(bad)
        for bad in variants:
            self.assert_blocked(rows, bad)

    def test_leading_nonempty_content_and_no_accepted_title_block(self):
        rows = ["unassigned content\n", "= A =\n", "body\n"]
        self.assert_blocked(rows, ledger_for(rows, [(1, "ACCEPT_TITLE")]))
        rows = ["\n", "= expression =\n"]
        self.assert_blocked(rows, ledger_for(rows, [(1, "BODY")]))

    def test_duplicate_content_fails_even_with_distinct_reviewed_source_rows(self):
        rows = ["= First =\n", "identical body\n", "= Second =\n", "identical body\n"]
        with self.assertRaises(BoundaryStop) as caught:
            prepare_partition(rows, ledger_for(rows, [(0, "ACCEPT_TITLE"), (2, "ACCEPT_TITLE")]), CORPUS)
        self.assertEqual(caught.exception.status, "FAIL")
        self.assertEqual(caught.exception.reason, "Duplicate body content")
        self.assertEqual(caught.exception.actual["first_heading_row"], 0)
        self.assertEqual(caught.exception.actual["second_heading_row"], 2)

    def test_source_identity_binds_position_corpus_and_title_not_content(self):
        rows = ["= A =\n", "original body\n"]
        first = prepare_partition(rows, ledger_for(rows, [(0, "ACCEPT_TITLE")]), CORPUS)["articles"][0]
        changed = ["= A =\n", "changed body\n"]
        second = prepare_partition(changed, ledger_for(changed, [(0, "ACCEPT_TITLE")]), CORPUS)["articles"][0]
        self.assertEqual(first["source_article_key"], second["source_article_key"])
        self.assertNotEqual(first["article_id"], second["article_id"])
        shifted = ["\n", "= A =\n", "original body\n"]
        third = prepare_partition(shifted, ledger_for(shifted, [(1, "ACCEPT_TITLE")]), CORPUS)["articles"][0]
        self.assertNotEqual(first["source_article_key"], third["source_article_key"])
        self.assertEqual(first["article_id"], third["article_id"])


if __name__ == "__main__":
    unittest.main()
